def _path_cost(G, path):
    """Total cost of a path using sanitized edge costs."""
    total = 0.0
    for i in range(len(path) - 1):
        c = G[path[i]][path[i + 1]].get("cost")
        if c is None or (isinstance(c, float) and c != c):
            return float("inf")
        total += c
    return total


def _route_dst(h, src, dst, dist, paths):
    """Pick the cheapest route from src to dst.

    Approach: use the cost-weighted Dijkstra path; additionally try a
    detour that penalizes the most expensive edge on that path (exploits
    alternate networks/links), then keep the cheaper of the two.
    """
    best = paths.get(dst)
    best_cost = dist.get(dst, float("inf"))
    if best is None:
        # Fallback: hop-count shortest path so every config still succeeds.
        try:
            best = nx.shortest_path(h, src, dst)
            best_cost = _path_cost(h, best)
        except Exception:
            return None
    if best_cost == float("inf"):
        return best

    # Detour: penalize the priciest edge on the current best path.
    try:
        edges = [(best[i], best[i + 1]) for i in range(len(best) - 1)]
        costly = max(edges, key=lambda e: h[e[0]][e[1]].get("cost") or 0)
        h2 = h.copy()
        h2[costly[0]][costly[1]]["cost"] += 1e9
        alt = nx.dijkstra_path(h2, src, dst, weight="cost")
        if _path_cost(h, alt) < best_cost:
            best = alt
    except Exception:
        pass
    return best


def search_algorithm(src, dsts, G, num_partitions):
    """Broadcast src's partitions to all dsts via cheapest routes.

    Strategy: sanitize invalid (None/NaN) edge costs, run ONE cost-weighted
    single-source Dijkstra from src, then for each dst pick the cheaper of
    (a) that path and (b) a detour around its most expensive edge. Fall
    back to hop-count paths for unreachable dsts so nothing fails.
    """
    h = G.copy()
    h.remove_edges_from(list(h.in_edges(src)) + list(nx.selfloop_edges(h)))

    # Sanitize missing / NaN costs so Dijkstra is always valid.
    for u, v, d in h.edges(data=True):
        c = d.get("cost")
        if c is None or (isinstance(c, float) and c != c):
            d["cost"] = 1e12

    try:
        dist, paths = nx.single_source_dijkstra(h, src, weight="cost")
    except Exception:
        dist, paths = {}, {}

    bc_topology = BroadCastTopology(src, dsts, num_partitions)
    for dst in dsts:
        path = _route_dst(h, src, dst, dist, paths)
        if path is None or len(path) < 2:
